window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[181]={"id":"181","numero":181,"titre":"Sécurité sanitaire & veille sanitaire","objectifs":[{"id":"181-1","rang":"A","rubrique":"Définitions","titre":"Connaître la définition de la sécurité sanitaire","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">sécurité sanitaire</span> est la <strong>protection de la santé de l'homme contre <span class=\"kw-clinique\">les</span> risques induits par le fonctionnement de la société</strong>, qu'ils soient <span class=\"kw-etio\">alimentaires</span>, <span class=\"kw-etio\">environnementaux</span> ou <span class=\"kw-etio\">sanitaires</span>.</div>\n      <ul>\n        <li>Concept <strong>inexistant en France avant <span class=\"kw-chiffre\">1993</span></strong> : il naît du drame du <span class=\"kw-etio\">sang contaminé</span> et de la réforme de la transfusion qui s'ensuit.</li>\n        <li>Construit ensuite <strong>par strates successives</strong>, en réaction aux <span class=\"kw-etio\">crises sanitaires</span> : <span class=\"kw-def\">vache folle</span> (<span class=\"kw-chiffre\">1996</span>), <span class=\"kw-def\">canicule</span> (<span class=\"kw-chiffre\">2003</span>), <span class=\"kw-def\">Mediator®</span> (<span class=\"kw-chiffre\">2010</span>).</li>\n        <li>Principe fondateur : <strong>dissocier l'<span class=\"kw-def\">évaluation</span> du risque (agences scientifiques) de la <span class=\"kw-def\">décision</span> politique</strong> (gestion du risque).</li>\n        <li>Devenue un <strong>objectif essentiel du système de santé</strong> et un enjeu de société.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-2","rang":"A","rubrique":"Définitions","titre":"Connaître la définition de la crise sanitaire","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">crise sanitaire</span> est une <strong>situation imprévue et complexe</strong>, présentant un <span class=\"kw-alerte\">caractère de gravité potentiel ou avéré</span>, et <strong>nécessitant des actions immédiates avec des moyens de gestion exceptionnels</strong>, le plus souvent <strong>transversaux</strong>.</div>\n      <ul>\n        <li>Source de la définition : <em>Glossaire des vigilances, <span class=\"kw-def\">Afssaps</span>, <span class=\"kw-chiffre\">2011</span></em>.</li>\n        <li>Trois ingrédients à retenir : <strong>imprévue</strong> + <strong>complexe / transversale</strong> + <span class=\"kw-alerte\">grave</span> → impose des <strong>moyens exceptionnels</strong>.</li>\n        <li>Exemples historiques : <span class=\"kw-etio\">sang contaminé</span>, <span class=\"kw-etio\">vache folle</span>, <span class=\"kw-etio\">canicule 2003</span>, <span class=\"kw-etio\">Mediator®</span>, <span class=\"kw-etio\">COVID-19</span>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-3","rang":"A","rubrique":"Définitions","titre":"Connaître la définition de la veille et de la vigilance sanitaire","contenu":"<div class=\"obj-callout success\"><strong>Veille sanitaire.</strong> Processus <strong>continu</strong> de <strong>recueil, identification, évaluation et invest<span class=\"kw-chiffre\">iga</span>tion</strong> des risques d'événements ou des <span class=\"kw-clinique\">événements indésirables</span> de toute nature associés à une <span class=\"kw-alerte\">menace potentielle pour la santé humaine</span>. Elle <strong>contribue à la <span class=\"kw-def\">sécurité sanitaire</span></strong>.</div>\n      <div class=\"obj-callout success\"><strong>Vigilance sanitaire.</strong> Ensemble des <strong>dispositifs réglementés de <span class=\"kw-def\">surveillance</span></strong> des <span class=\"kw-clinique\">événements indésirables</span> et des <span class=\"kw-clinique\">incidents</span> survenant chez l'homme. Initialement liés aux <span class=\"kw-def\">produits de santé</span>, ils s'élargissent aux <span class=\"kw-def\">infections nosocomiales</span> et aux <span class=\"kw-alerte\">EIGS</span> liés aux soins.</div>\n      <ul>\n        <li>La <span class=\"kw-def\">veille sanitaire</span> regroupe notamment <span class=\"kw-clinique\">les</span> <strong>vigilances réglementées</strong> et les <span class=\"kw-def\">maladies à déclaration obligatoire (MDO)</span>.</li>\n        <li>À distinguer de la <span class=\"kw-def\">surveillance sanitaire</span> : collecte, analyse et diffusion <strong>systématiques et continues</strong> de données de <span class=\"kw-bio\">morbidité</span> et de <span class=\"kw-bio\">mortalité</span> (aide à la décision en santé publique).</li>\n        <li><strong>Repère :</strong> <span class=\"kw-def\">veille</span> = guetter le signal ; <span class=\"kw-def\">vigilance</span> = dispositif réglementé ciblé ; <span class=\"kw-def\">surveillance</span> = mesurer en continu.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 4 — Sécurité du patient, gestions des risques, EI</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-4","rang":"A","rubrique":"Définitions","titre":"Connaître la définition des produits de santé destinés à l'homme","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">produits de santé destinés à l'homme</span> couvrent <strong>quatre grands ensembles</strong> (champ de compétence de l'<span class=\"kw-def\">ANSM</span>) :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Médicaments</span></strong></td>\n            <td>Tous <span class=\"kw-clinique\">les</span> médicaments (<strong>avant et après <span class=\"kw-def\">AMM</span></strong>) et matières premières ; <span class=\"kw-ttt\">médicaments dérivés du sang</span> ; <span class=\"kw-ttt\">stupéfiants et psychotropes</span> ; <span class=\"kw-ttt\">vaccins</span> ; produits homéopathiques et à base de plantes ; <span class=\"kw-ttt\">préparations magistrales et hospitalières</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Produits biologiques</span></strong></td>\n            <td><span class=\"kw-def\">Organes</span>, <span class=\"kw-def\">tissus</span>, <span class=\"kw-def\">cellules</span> à fins thérapeutiques ; produits de <span class=\"kw-def\">thérapie cellulaire et génique</span> ; <span class=\"kw-def\">produits sanguins labiles (PSL)</span> ; produits thérapeutiques annexes</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Dispositifs médicaux</span></strong></td>\n            <td>DM thérapeutiques, de diagnostic, de <span class=\"kw-bio\">diagnostic in vitro (DIV)</span>, des plateaux techniques</td>\n          </tr>\n          <tr>\n            <td><strong>Cosmétiques & tatouage</strong></td>\n            <td><span class=\"kw-def\">Produits cosmétiques</span> et <span class=\"kw-def\">produits de tatouage</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le périmètre suit le produit <strong>tout au long de son cycle de vie</strong>, depuis <span class=\"kw-clinique\">les</span> essais initiaux jusqu'à la <span class=\"kw-def\">surveillance</span> après mise sur le marché.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-5","rang":"B","rubrique":"Définitions","titre":"Connaître les principes de sécurité sanitaire : principe d'évaluation","contenu":"<div class=\"callout callout-info\"><strong>Cadre.</strong> <span class=\"kw-chiffre\">Quatre</span> grands principes structurent le dispositif de <span class=\"kw-def\">sécurité sanitaire</span> : <strong>évaluation</strong>, <strong>précaution</strong>, <strong>impartialité</strong>, <strong>transparence</strong>.</div>\n      <ul>\n        <li><span class=\"kw-def\">Principe d'évaluation</span> : professionnels, autorités et gestionnaires doivent disposer d'une <strong>capacité de détection et d'analyse des risques</strong>.</li>\n        <li>Obl<span class=\"kw-chiffre\">iga</span>tion de <strong>connaître <span class=\"kw-clinique\">les</span> effets des décisions</strong> prises → évaluer ses actes <strong>a priori et a posteriori</strong>.</li>\n        <li>La <span class=\"kw-def\">sécurité des patients</span> repose sur la capacité de <strong>choisir entre différents risques</strong>, en <strong>mettant en balance <span class=\"kw-clinique\">les</span> bénéfices attendus</strong> (analyse <span class=\"kw-def\">bénéfice/risque</span>).</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-6","rang":"B","rubrique":"Définitions","titre":"Connaître les principes de sécurité sanitaire : principe de précaution","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> <span class=\"kw-def\">Principe de précaution</span> : <strong>l'absence de certitudes</strong>, compte tenu des connaissances scientifiques et techniques du moment, <strong>ne doit pas retarder l'adoption de mesures</strong> visant à prévenir <strong>a priori</strong> un risque de <span class=\"kw-alerte\">dommages graves et irréversibles</span>, <strong>à un coût économiquement acceptable</strong>.</div>\n      <ul>\n        <li>Mots-clés EDN : <strong>incertitude scientifique</strong> + <span class=\"kw-alerte\">dommage grave et irréversible</span> + action <strong>a priori</strong> + <strong>coût acceptable</strong>.</li>\n        <li>Ne pas confondre avec le <span class=\"kw-def\">principe de prévention</span> (risque connu et avéré) : ici le risque est <strong>incertain / hypothétique</strong>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-7","rang":"B","rubrique":"Définitions","titre":"Connaître les principes de sécurité sanitaire : principe d'impartialité","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> <span class=\"kw-def\">Principe d'impartialité</span> : garantir <strong>l'indépendance des autorités et des professionnels de santé</strong> et <strong>l'absence de liens financiers entre <span class=\"kw-clinique\">les</span> experts et les industriels</strong>, pour éviter les <span class=\"kw-alerte\">conflits d'intérêts</span>.</div>\n      <ul>\n        <li>Vise <span class=\"kw-clinique\">les</span> risques liés aux <span class=\"kw-alerte\">conflits d'intérêts</span> favorisés par l'organisation administrative et professionnelle.</li>\n        <li>Traductions concrètes : <strong>déclarations publiques d'intérêts (DPI)</strong>, déport en cas de lien, <strong>transparence des liens experts ↔ industrie</strong>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-8","rang":"B","rubrique":"Définitions","titre":"Connaître les principes de sécurité sanitaire : principe de transparence","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> <span class=\"kw-def\">Principe de transparence</span> : <strong>l'information de la population doit être effective</strong>, de même que <span class=\"kw-clinique\">les</span> <strong>échanges et la controverse</strong> entre scientifiques, associations et autorités sanitaires.</div>\n      <ul>\n        <li>Objectif : prendre <span class=\"kw-clinique\">les</span> <strong>décisions adaptées à la situation</strong> à un moment donné, et <strong>réviser ces décisions</strong> chaque fois que nécessaire.</li>\n        <li>Le dispositif global s'appuie sur : une <strong>expertise scientifique forte</strong>, une <strong>capacité d'alerte rapide</strong>, la <strong>transparence</strong> de la décision et une <strong>autonomie juridique et financière des agences</strong>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-9","rang":"A","rubrique":"Définitions","titre":"Connaître la pharmacovigilance","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">pharmacovigilance</span> = <span class=\"kw-def\">surveillance</span>, évaluation, prévention et gestion du <span class=\"kw-etio\">risque d'effet indésirable</span> résultant de l'utilisation des <span class=\"kw-ttt\">médicaments</span> et produits à usage humain. Vigilance pilotée par l'<span class=\"kw-def\">ANSM</span>.</div>\n      <ul>\n        <li><strong>Quoi déclarer ?</strong> Tout <span class=\"kw-clinique\">effet indésirable</span> suspecté (<span class=\"kw-alerte\">grave ou non</span>), quel que soit le contexte (usage <strong>conforme ou non à l'AMM</strong>, <span class=\"kw-etio\">erreur médicamenteuse</span>, <span class=\"kw-etio\">abus</span>, <span class=\"kw-etio\">mésusage</span>, <span class=\"kw-etio\">surdosage</span>, <span class=\"kw-etio\">exposition professionnelle</span>). Particulièrement <span class=\"kw-clinique\">les</span> effets <span class=\"kw-alerte\">graves</span> et <span class=\"kw-alerte\">inattendus</span>.</li>\n        <li><strong>Qui déclare ?</strong> <span class=\"kw-ttt\">Médecins</span>, <span class=\"kw-ttt\">sages-femmes</span>, <span class=\"kw-ttt\">chirurgiens-dentistes</span>, <span class=\"kw-ttt\">pharmaciens</span> → <strong>obl<span class=\"kw-chiffre\">iga</span>tion</strong>. Autres professionnels, <strong>patients</strong> et associations → <strong>possible</strong>. Firmes pharmaceutiques → via <span class=\"kw-def\">Eudravigilance</span>.</li>\n        <li><strong>À qui ?</strong> Au <span class=\"kw-def\">Centre régional de pharmacovigilance (CRPV)</span> du déclarant ; <span class=\"kw-clinique\">les</span> entreprises déclarent à l'<span class=\"kw-def\">EMA</span> via <span class=\"kw-def\">Eudravigilance</span>.</li>\n        <li><strong>Comment ?</strong> <span class=\"kw-def\">Portail national</span> de <span class=\"kw-def\">signalement</span> des événements sanitaires indésirables (<em>signalement-sante.gouv.fr</em>), courrier, fax, CERFA, application.</li>\n        <li><strong>Suites :</strong> le <span class=\"kw-def\">CRPV</span> transmet à l'<span class=\"kw-def\">ANSM</span> → mesures (information des professionnels, <span class=\"kw-def\">modification du RCP</span>, <span class=\"kw-alerte\">retrait ou suspension d'AMM</span>, lettres d'alerte, pictogrammes).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 325 — Gestions des risques liés aux médicaments (<span class=\"kw-etio\">iatrogène</span>, erreur)</em></p>","frequence":2},{"id":"181-10","rang":"A","rubrique":"Définitions","titre":"Connaître la pharmacodépendance ou addictovigilance","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> L'<span class=\"kw-def\">addictovigilance</span> (pharmacodépendance) = <span class=\"kw-def\">surveillance</span> de l'<span class=\"kw-etio\">abus</span>, de la <span class=\"kw-etio\">dépendance</span> et des <span class=\"kw-etio\">usages détournés</span> liés à la consommation de toute <strong>substance ou plante à effet psychoactif</strong> et des médicaments en contenant. Vigilance pilotée par l'<span class=\"kw-def\">ANSM</span>.</div>\n      <ul>\n        <li><span class=\"kw-alerte\">Exclusions :</span> <strong><span class=\"kw-etio\">alcool</span> éthylique</strong> et <strong>tabac</strong>.</li>\n        <li><strong>Quoi déclarer ?</strong> <span class=\"kw-alerte\">Pharmacodépendance grave</span>, <span class=\"kw-alerte\">abus grave</span> ou <span class=\"kw-alerte\">usage détourné (mésusage) grave</span>.</li>\n        <li><strong>Qui déclare ?</strong> <span class=\"kw-ttt\">Médecin</span>, <span class=\"kw-ttt\">chirurgien-dentiste</span>, <span class=\"kw-ttt\">pharmacien</span>, <span class=\"kw-ttt\">sage-femme</span> → <strong>obl<span class=\"kw-chiffre\">iga</span>toire</strong> ; autres professionnels et usagers → possible.</li>\n        <li><strong>À qui ?</strong> Au <span class=\"kw-def\">CEIP-A</span> (Centre d'évaluation et d'information sur la pharmacodépendance et l'addictovigilance) du territoire ; l'<span class=\"kw-def\">ANSM</span> pilote le réseau des <span class=\"kw-chiffre\">13</span> CEIP-A.</li>\n        <li>Contribue à la <strong>politique de lutte contre la drogue</strong> (classement des produits sur la liste des <span class=\"kw-def\">stupéfiants</span> et <span class=\"kw-def\">psychotropes</span>).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 325 — Gestions des risques liés aux médicaments (<span class=\"kw-etio\">iatrogène</span>, erreur)</em></p>","frequence":0},{"id":"181-11","rang":"A","rubrique":"Définitions","titre":"Connaître l'hémovigilance","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> L'<span class=\"kw-def\">hémovigilance</span> = <span class=\"kw-def\">surveillance</span>, évaluation et prévention des <span class=\"kw-clinique\">incidents</span> et <span class=\"kw-clinique\">effets indésirables</span> survenant chez <span class=\"kw-clinique\">les</span> <strong>donneurs</strong> ou les <strong>receveurs</strong> de <span class=\"kw-def\">PSL</span>, sur <strong>toute la chaîne transfusionnelle</strong>. Vigilance pilotée par l'<span class=\"kw-def\">ANSM</span>.</div>\n      <ul>\n        <li><strong>Que déclarer ?</strong> <span class=\"kw-clinique\">Effet indésirable receveur</span> → <strong>FEIR</strong> ; <span class=\"kw-alerte\">effet indésirable grave donneur</span> → <strong>FEIGD</strong> ; information post-don → <strong>FIPD</strong> ; <span class=\"kw-alerte\">incident grave</span> de la chaîne → <strong>FIG</strong>.</li>\n        <li><strong>Acteurs :</strong> niveau national (<span class=\"kw-def\">ANSM</span>, <span class=\"kw-def\">Santé publique France</span>, <span class=\"kw-def\">EFS</span>) ; niveau régional (coordonnateurs / correspondants régionaux) ; niveau local (correspondants des <span class=\"kw-def\">ETS</span> et établissements de soins, <strong>tout professionnel de santé</strong>).</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>EIR — repères de <span class=\"kw-def\">classification</span>.</strong>\n        <ul>\n          <li><strong>Délai :</strong> <span class=\"kw-clinique\">immédiat</span> (≤ <span class=\"kw-chiffre\">8 jours</span>, aigu pendant et dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24 h</span>) <span class=\"kw-bio\">vs</span> <span class=\"kw-clinique\">retardé</span> (&gt; <span class=\"kw-chiffre\">8 jours</span>)</li>\n          <li><strong>Sévérité :</strong> <span class=\"kw-def\">grade</span> <span class=\"kw-chiffre\">1</span> non sévère ; grade <span class=\"kw-chiffre\">2</span> sévère ; grade <span class=\"kw-chiffre\">3</span> <span class=\"kw-alerte\">menace vitale</span> ; grade <span class=\"kw-chiffre\">4</span> <span class=\"kw-alerte\">décès</span></li>\n          <li><strong>Imputabilité :</strong> NE (non évaluable), <span class=\"kw-chiffre\">0</span> (exclue), <span class=\"kw-chiffre\">1</span> (possible), <span class=\"kw-chiffre\">2</span> (probable), <span class=\"kw-chiffre\">3</span> (certaine)</li>\n        </ul>\n      </div>\n      <p>EIR <span class=\"kw-clinique\">les</span> plus fréquents : <span class=\"kw-clinique\">réactions allergiques</span>, <span class=\"kw-clinique\">réactions fébriles non hémolytiques</span>, <span class=\"kw-clinique\">œdème de surcharge</span> (1ʳᵉ cause de <span class=\"kw-def\">mortalité</span>), <span class=\"kw-clinique\">incompatibilités immunologiques</span>.</p>","frequence":0},{"id":"181-12","rang":"B","rubrique":"Définitions","titre":"Connaître la matériovigilance","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">matériovigilance</span> = <span class=\"kw-def\">surveillance</span> des <span class=\"kw-clinique\">incidents</span> ou <span class=\"kw-clinique\">risques d'incident</span> mettant en cause un <span class=\"kw-def\">dispositif médical (DM)</span> mis sur le marché, afin de prendre <span class=\"kw-clinique\">les</span> mesures préventives et/ou correctives. Vigilance pilotée par l'<span class=\"kw-def\">ANSM</span>.</div>\n      <ul>\n        <li><strong>Quoi déclarer ?</strong> Tout <span class=\"kw-alerte\">incident ou risque d'incident grave</span> → <strong><span class=\"kw-def\">signalement</span> sans délai</strong> ; <span class=\"kw-clinique\">les</span> autres événements → facultatif.</li>\n        <li><strong>Qui déclare ?</strong> Fabricants ou mandataires, utilisateurs, tiers (distributeurs).</li>\n        <li><strong>À qui ?</strong> Professionnels libéraux et fabricants → directement au <strong>directeur général de l'<span class=\"kw-def\">ANSM</span></strong> ; en établissement → <span class=\"kw-def\">correspondant local de matériovigilance</span> (interface utilisateur ↔ ANSM ↔ fabricant). Si le DM administre un médicament (ex. <span class=\"kw-ttt\">stents actifs</span>) → également le <span class=\"kw-def\">CRPV</span>.</li>\n        <li><strong>Suites :</strong> informations/recommandations de l'ANSM, <strong>actions correctives ou rappels</strong> du fabricant validés par l'ANSM, <span class=\"kw-alerte\">décisions de police sanitaire</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 325 — Gestions des risques liés aux médicaments (<span class=\"kw-etio\">iatrogène</span>, erreur)</em></p>","frequence":0},{"id":"181-13","rang":"B","rubrique":"Définitions","titre":"Connaître la réactovigilance","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">réactovigilance</span> = <span class=\"kw-def\">surveillance</span> des <span class=\"kw-clinique\">incidents</span> et risques liés aux <span class=\"kw-bio\">dispositifs médicaux de diagnostic in vitro (DM-DIV)</span> : <span class=\"kw-bio\">analyses biologiques</span> et <span class=\"kw-bio\">réactifs de laboratoire</span>. Vigilance pilotée par l'<span class=\"kw-def\">ANSM</span>.</div>\n      <div class=\"callout callout-info\"><strong>Discriminant.</strong> <span class=\"kw-def\">Matériovigilance</span> = dispositifs médicaux « classiques » ; <span class=\"kw-def\">réactovigilance</span> = dispositifs de <strong>diagnostic in vitro</strong> (le test, le réactif, l'automate de biologie).</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-14","rang":"B","rubrique":"Définitions","titre":"Connaître la cosmétovigilance","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">cosmétovigilance</span> = <span class=\"kw-def\">surveillance</span> des <span class=\"kw-clinique\">effets indésirables</span> liés à l'utilisation des <span class=\"kw-def\">produits cosmétiques</span>. Vigilance pilotée par l'<span class=\"kw-def\">ANSM</span>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-15","rang":"B","rubrique":"Définitions","titre":"Connaître la vigilance des produits de tatouage","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">tatouvigilance</span> (vigilance des produits de tatouage) = <span class=\"kw-def\">surveillance</span> des <span class=\"kw-clinique\">effets indésirables</span> liés à l'utilisation des <span class=\"kw-def\">produits de tatouage</span>. Vigilance pilotée par l'<span class=\"kw-def\">ANSM</span>.</div>\n      <div class=\"callout callout-info\"><strong>Récap des 8 vigilances ANSM.</strong> <span class=\"kw-def\">Pharmacovigilance</span> · <span class=\"kw-def\">addictovigilance</span> · <span class=\"kw-def\">hémovigilance</span> · <span class=\"kw-def\">matériovigilance</span> · <span class=\"kw-def\">réactovigilance</span> · <span class=\"kw-def\">cosmétovigilance</span> · <span class=\"kw-def\">tatouvigilance</span> · <span class=\"kw-def\">vigilance des essais cliniques</span>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-16","rang":"A","rubrique":"Définitions","titre":"Connaître l'identitovigilance","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> L'<span class=\"kw-def\">identitovigilance</span> = <strong>prévention des erreurs d'identité</strong> des patients à toutes <span class=\"kw-clinique\">les</span> étapes du processus de soins (notamment en établissement de santé). C'est la <strong>« dernière-née »</strong> des vigilances.</div>\n      <ul>\n        <li>Mesures concrètes : <strong>bracelet d'identification</strong> du patient, <strong>vérification de l'identité avant tout acte de soins</strong>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Piège EDN.</strong> L'<span class=\"kw-def\">identitovigilance</span> <strong>n'est PAS une vigilance pilotée par l'<span class=\"kw-def\">ANSM</span></strong> (ce n'est pas un produit de santé) : c'est un <strong>dispositif élargi de sécurité des soins</strong>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-17","rang":"A","rubrique":"Définitions","titre":"Connaître l'infectiovigilance","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> L'<span class=\"kw-def\">infectiovigilance</span> = <strong>veille des <span class=\"kw-def\">infections associées aux soins (IAS)</span></strong>. Elle est <strong>gérée par <span class=\"kw-def\">Santé publique France</span></strong>.</div>\n      <div class=\"callout callout-danger\"><strong>Piège EDN classique.</strong> L'<span class=\"kw-def\">infectiovigilance</span> est sous la responsabilité de <span class=\"kw-def\">Santé publique France</span>, <strong>PAS de l'<span class=\"kw-def\">ANSM</span></strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 4 — Sécurité du patient, gestions des risques, EI</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-18","rang":"B","rubrique":"Définitions","titre":"Connaître la toxicovigilance","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">toxicovigilance</span> = <span class=\"kw-def\">surveillance</span> des <span class=\"kw-alerte\">effets toxiques</span> pour l'homme de l'exposition à un <strong>mélange ou une substance</strong> (<span class=\"kw-etio\">naturelle ou de synthèse</span>), disponible sur le marché ou présente dans l'environnement.</div>\n      <div class=\"callout callout-danger\"><strong>Piège EDN.</strong> La <span class=\"kw-def\">toxicovigilance</span> relève de l'<span class=\"kw-def\">ANSES</span> (et des <strong>centres antipoison</strong> depuis <span class=\"kw-chiffre\">2016</span>), <strong>PAS de l'<span class=\"kw-def\">ANSM</span></strong>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-19","rang":"B","rubrique":"Définitions","titre":"Connaître la nutrivigilance","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">nutrivigilance</span> = <span class=\"kw-def\">surveillance</span> des <span class=\"kw-clinique\">effets indésirables</span> liés à la consommation de certaines <strong>denrées alimentaires</strong>, dont <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">compléments alimentaires</span>.</div>\n      <div class=\"callout callout-danger\"><strong>Piège EDN.</strong> La <span class=\"kw-def\">nutrivigilance</span> est gérée par l'<span class=\"kw-def\">ANSES</span>, <strong>PAS par l'<span class=\"kw-def\">ANSM</span></strong>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-20","rang":"B","rubrique":"Définitions","titre":"Connaître la biovigilance","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">biovigilance</span> = <span class=\"kw-def\">surveillance</span> des <span class=\"kw-etio\">risques liés à l'utilisation à des fins thérapeutiques</span> d'<strong>éléments et produits issus du corps humain</strong> : <span class=\"kw-def\">organes</span>, <span class=\"kw-def\">tissus</span>, <span class=\"kw-def\">cellules</span> et <span class=\"kw-def\">lait maternel</span> à usage thérapeutique.</div>\n      <div class=\"callout callout-danger\"><strong>Piège EDN.</strong> La <span class=\"kw-def\">biovigilance</span> (et l'<span class=\"kw-def\">AMP-vigilance</span>) est gérée par l'<span class=\"kw-def\">Agence de la biomédecine</span>, <strong>PAS par l'<span class=\"kw-def\">ANSM</span></strong>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-21","rang":"B","rubrique":"Définitions","titre":"Connaître l'ANSM, ses missions, son organisation","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> L'<span class=\"kw-def\">ANSM</span> (Agence nationale de sécurité du médicament et des produits de santé) est un <strong>établissement public sous tutelle du ministère de la Santé</strong>, créé par la loi du <span class=\"kw-chiffre\">29 décembre 2011</span> (en place le <span class=\"kw-chiffre\">1ᵉʳ mai 2012</span>). Mission : <strong>garantir la sécurité des <span class=\"kw-def\">produits de santé</span></strong> destinés à l'homme tout au long de leur cycle de vie.</div>\n      <p><strong>Missions</strong> (évaluer sécurité d'emploi, efficacité, qualité) :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Surveillance</span> continue</strong> des <span class=\"kw-clinique\">effets indésirables</span> (prévisibles ou inattendus)</li>\n        <li><strong>Inspection</strong> des établissements (fabrication, importation, distribution, <span class=\"kw-def\">pharmacovigilance</span>, <span class=\"kw-def\">essais cliniques</span>)</li>\n        <li><strong>Contrôle en laboratoire</strong> des lots de <span class=\"kw-ttt\">vaccins</span> et de <span class=\"kw-ttt\">médicaments dérivés du sang</span></li>\n        <li><strong>Contrôle des produits</strong> du marché (inspections, saisies des douanes / justice)</li>\n        <li><strong>Information</strong> sur <span class=\"kw-clinique\">les</span> bénéfices et les risques</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Décisions de police sanitaire.</strong> <span class=\"kw-def\">AMM</span> (+ retrait / suspension) · autorisation d'<span class=\"kw-def\">essais cliniques</span> · <span class=\"kw-def\">ATU</span> (autorisation temporaire d'utilisation) · <span class=\"kw-def\">RTU</span> (recommandation temporaire d'utilisation).</div>\n      <p><strong>Organisation :</strong> pilote <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">8</span> vigilances ; au niveau régional s'appuie sur les <span class=\"kw-def\">CRPV</span> (pharmacovigilance) et les <span class=\"kw-def\">CEIP-A</span> (addictovigilance).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 325 — Gestions des risques liés aux médicaments (<span class=\"kw-etio\">iatrogène</span>, erreur)</em></p>","frequence":0},{"id":"181-22","rang":"B","rubrique":"Définitions","titre":"Connaître l'Anses","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> L'<span class=\"kw-def\">ANSES</span> (Agence nationale de sécurité sanitaire de l'alimentation, de l'environnement et du travail) contribue à assurer la <span class=\"kw-def\">sécurité sanitaire</span> humaine dans <span class=\"kw-clinique\">les</span> domaines de l'<span class=\"kw-etio\">environnement</span>, du <span class=\"kw-etio\">travail</span> et de l'<span class=\"kw-etio\">alimentation</span>.</div>\n      <ul>\n        <li>Missions de <strong>veille, expertise, recherche et référence</strong> ; couvre aussi la santé/le bien-être <strong>animal</strong> et <strong>végétal</strong> et <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">médicaments vétérinaires</span>.</li>\n        <li><strong>Vigilances gérées :</strong> <span class=\"kw-def\">toxicovigilance</span> (+ centres antipoison) · <span class=\"kw-def\">nutrivigilance</span> · <span class=\"kw-def\">pharmacovigilance vétérinaire</span> · <span class=\"kw-def\">phytopharmacovigilance</span>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-23","rang":"B","rubrique":"Définitions","titre":"Connaître l'Agence de la biomédecine","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> L'<span class=\"kw-def\">Agence de la biomédecine (ABM)</span>, créée par la <strong>loi bioéthique de <span class=\"kw-chiffre\">2004</span></strong>, est une agence de l'État compétente pour le <strong>prélèvement et la greffe</strong> d'<span class=\"kw-def\">organes</span>, <span class=\"kw-def\">tissus</span> et <span class=\"kw-def\">cellules</span>, ainsi que la <span class=\"kw-def\">procréation (AMP)</span>, l'<span class=\"kw-def\">embryologie</span> et la <span class=\"kw-def\">génétique humaines</span>.</div>\n      <ul>\n        <li>Assure <span class=\"kw-clinique\">les</span> règles de <strong>sécurité sanitaire, d'éthique et d'équité</strong> ; autorité de référence sur les aspects médicaux, scientifiques et éthiques liés aux greffes.</li>\n        <li><strong>Vigilances gérées :</strong> <span class=\"kw-def\">biovigilance</span> · <span class=\"kw-def\">AMP-vigilance</span>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-24","rang":"B","rubrique":"Définitions","titre":"Connaître la Haute Autorité de Santé : le dispositif de déclaration des événements porteurs de risque","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">HAS</span> est chargée du <strong>recueil des <span class=\"kw-def\">événements porteurs de risque (EPR)</span></strong> déclarés dans le cadre de la <strong>démarche d'<span class=\"kw-def\">accréditation des médecins</span></strong> exerçant des spécialités à risque.</div>\n      <ul>\n        <li>Un <span class=\"kw-def\">EPR</span> est un <strong>événement qui aurait pu causer un dommage</strong> mais ne l'a pas fait (« <span class=\"kw-def\">presque-accident</span> », <em><span class=\"kw-def\">near-miss</span></em>) → leur déclaration permet un <strong>retour d'expérience</strong> avant survenue d'un <span class=\"kw-alerte\">événement indésirable grave</span>.</li>\n        <li>À distinguer du circuit des <span class=\"kw-alerte\">EIGS</span> (déclarés via le portail national → <span class=\"kw-def\">ARS</span> → base HAS pour retour d'expérience).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 4 — Sécurité du patient, gestions des risques, EI</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-25","rang":"B","rubrique":"Définitions","titre":"Connaître la Haute Autorité de Santé : ses missions dans la qualité et sécurité des soins","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> La <span class=\"kw-def\">HAS</span> (créée par la loi du <span class=\"kw-chiffre\">13 août 2004</span>) est un <strong>organisme d'expertise scientifique, consultatif et indépendant</strong> qui contribue à la régulation du système de santé par l'amélioration de la <span class=\"kw-def\">qualité</span> et l'<span class=\"kw-def\">efficience</span>.</div>\n      <ul>\n        <li><strong>Évaluer l'utilité médicale</strong> de l'ensemble des actes, prestations et produits de santé pris en charge par l'<span class=\"kw-def\">Assurance maladie</span></li>\n        <li>Mettre en œuvre la <strong><span class=\"kw-def\">certification des établissements de santé</span></strong></li>\n        <li><strong>Promouvoir <span class=\"kw-clinique\">les</span> bonnes pratiques</strong> et le <strong>bon usage des soins</strong> (guides, référentiels, indicateurs, méthodes)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span class=\"kw-def\">HAS</span> <strong>ne gère aucune vigilance réglementée</strong>, mais participe à la <span class=\"kw-def\">sécurité sanitaire</span> par la promotion de la <strong>qualité et de la sécurité du patient</strong> (<span class=\"kw-def\">DPC</span>, <span class=\"kw-def\">certification</span>, <span class=\"kw-def\">EPR</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 4 — Sécurité du patient, gestions des risques, EI</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-26","rang":"B","rubrique":"Définitions","titre":"Connaître Santé Publique France, les centres nationaux de référence et leurs missions","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> <span class=\"kw-def\">Santé publique France (SpF)</span>, créée en <span class=\"kw-chiffre\">2016</span>, résulte de la <strong>fusion de l'<span class=\"kw-def\">InVS</span>, de l'<span class=\"kw-def\">INPES</span> et de l'<span class=\"kw-def\">EPRUS</span></strong>. C'est l'agence nationale de <strong>veille et de <span class=\"kw-def\">surveillance</span> sanitaire</strong>.</div>\n      <p><strong>Trois missions :</strong></p>\n      <ul>\n        <li><strong>Anticiper</strong> : détecter <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">risques sanitaires</span> par la <span class=\"kw-def\">surveillance</span> permanente de l'état de santé (<span class=\"kw-etio\">maladies infectieuses</span>, <span class=\"kw-etio\">environnement</span>, <span class=\"kw-etio\">risques professionnels</span>, <span class=\"kw-etio\">maladies chroniques</span>)</li>\n        <li><strong>Comprendre</strong> : système de <span class=\"kw-def\">veille et vigilance sanitaires</span>, connaissance de l'état de santé, comportements, risques</li>\n        <li><strong>Agir</strong> : promotion de la santé, <span class=\"kw-def\">alertes sanitaires</span> au ministre, réponse aux <span class=\"kw-alerte\">crises sanitaires</span></li>\n      </ul>\n      <ul>\n        <li><strong>Gère :</strong> l'<span class=\"kw-def\">infectiovigilance</span> (veille des <span class=\"kw-def\">IAS</span>) et <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">36</span> <span class=\"kw-def\">maladies à déclaration obligatoire (MDO)</span>.</li>\n        <li>S'appuie sur des réseaux : <span class=\"kw-def\">réseau Sentinelles</span>, registres de <span class=\"kw-def\">morbidité</span>, et <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">Centres nationaux de référence (CNR)</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Centres nationaux de référence (CNR).</strong> Laboratoires publics ou privés (santé, enseignement, recherche) assurant des missions d'<strong>expertise</strong>, <strong>conseil</strong>, <strong><span class=\"kw-def\">surveillance</span></strong> et <strong>alerte</strong> spécifiques à certains <span class=\"kw-etio\">micro-organismes pathogènes</span> (surveillance des maladies transmissibles).</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0},{"id":"181-27","rang":"A","rubrique":"Définitions","titre":"Savoir qu'il existe une liste des événements qui ne devraient jamais arriver en établissement de santé selon l'ANSM","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">« never events »</span> (événements qui ne devraient jamais arriver) sont des <span class=\"kw-alerte\">EIGS évitables</span> liés à des produits de santé, qui ne devraient pas survenir si des <strong>mesures de prévention adéquates</strong> sont mises en œuvre. Une liste de <span class=\"kw-chiffre\">12</span> événements a été établie par l'<span class=\"kw-def\">ANSM</span> en <span class=\"kw-chiffre\">2012</span>.</div>\n      <p><span class=\"kw-clinique\">Les</span> <span class=\"kw-chiffre\">12</span> never events portent essentiellement sur le <strong>médicament</strong> et son <span class=\"kw-etio\">administration</span> :</p>\n      <ul>\n        <li>Erreur de prise en charge des patients sous <span class=\"kw-ttt\">anticoagulants</span></li>\n        <li>Erreur d'administration du <span class=\"kw-ttt\">chlorure de potassium (KCl) injectable</span></li>\n        <li>Erreur de préparation de spécialités injectables à risque</li>\n        <li>Erreur d'administration par voie <span class=\"kw-alerte\">intrathécale au lieu d'IV</span></li>\n        <li>Erreur d'administration par voie <span class=\"kw-alerte\">parentérale au lieu de la voie orale/entérale</span></li>\n        <li><span class=\"kw-alerte\">Surdosage</span> en <span class=\"kw-ttt\">anticancéreux</span> (notamment en pédiatrie)</li>\n        <li>Erreur de rythme d'administration du <span class=\"kw-ttt\">méthotrexate</span> per os (hors cancérologie)</li>\n        <li>Erreur d'administration d'<span class=\"kw-ttt\">insuline</span></li>\n        <li>Erreur d'administration de spécialités d'<span class=\"kw-ttt\">anesthésie-réanimation</span> au bloc</li>\n        <li>Erreur d'administration de <span class=\"kw-ttt\">gaz à usage médical</span></li>\n        <li>Erreur de programmation des dispositifs d'administration (<span class=\"kw-ttt\">pompes à perfusion</span>, seringues électriques)</li>\n        <li>Erreur lors de l'utilisation de petits conditionnements unidoses plastique (sérum physiologique, antiseptique) — maternité / pédiatrie</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 4 — Sécurité du patient, gestions des risques, EI</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique (item 181).</em></p>","frequence":0}],"astuces":[],"strategie":{},"cards":[{"i":"58b0969aafb3","n":181,"o":"181-1","u":"Définitions","t":"Connaître la définition de la sécurité sanitaire","q":"Quel principe fondamental régit la sécurité sanitaire en France ?","a":"<p>Le principe fondamental est de <strong>dissocier l'évaluation du risque</strong> (réalisée par des agences scientifiques) de la <strong>décision politique de gestion du risque</strong>.</p>"},{"i":"e87d8b3d8d93","n":181,"o":"181-1","u":"Définitions","t":"Connaître la définition de la sécurité sanitaire","q":"Quel événement majeur a marqué l'émergence du concept de sécurité sanitaire en France ?","a":"<p>Le concept de sécurité sanitaire est apparu en France à la suite du <strong>drame du sang contaminé en 1993</strong> et la réforme de la transfusion sanguine qui en a découlé.</p>"},{"i":"ef1e90a75900","n":181,"o":"181-1","u":"Définitions","t":"Connaître la définition de la sécurité sanitaire","q":"Quelle est la définition de la sécurité sanitaire en France ?","a":"<p>La sécurité sanitaire est la <strong>protection de la santé de l'Homme</strong> contre les <strong>risques induits par le fonctionnement de la société</strong>, qu'ils soient alimentaires, environnementaux ou sanitaires.</p>"},{"i":"042ef946a8ba","n":181,"o":"181-10","u":"Définitions","t":"Connaître la pharmacodépendance ou addictovigilance","q":"Quelle est la définition de l'addictovigilance ou pharmacodépendance en France ?","a":"<p>L'<strong>addictovigilance</strong> est un système de surveillance de l'<strong>abus</strong>, de la <strong>dépendance</strong> et des <strong>usages détournés</strong> liés à la consommation de toute substance ou plante à effet psychoactif, ainsi que des médicaments en contenant.</p><p>Elle est pilotée par l'<strong>ANSM</strong> (Agence nationale de sécurité du médicament et des produits de santé).</p>"},{"i":"85461291cc1c","n":181,"o":"181-10","u":"Définitions","t":"Connaître la pharmacodépendance ou addictovigilance","q":"Quels types d'événements liés aux substances psychoactives doivent être obligatoirement déclarés dans le cadre de l'addictovigilance ?","a":"<p>Doivent être déclarés les cas de <strong>pharmacodépendance grave</strong>, d'<strong>abus grave</strong> ou d'<strong>usage détourné (mésusage) grave</strong>.</p>"},{"i":"bc2004156aa2","n":181,"o":"181-10","u":"Définitions","t":"Connaître la pharmacodépendance ou addictovigilance","q":"Qui a l'obligation de déclarer un événement d'addictovigilance et à quelle structure ?","a":"<ul><li>La déclaration est <strong>obligatoire</strong> pour les <strong>médecins</strong>, <strong>chirurgiens-dentistes</strong>, <strong>pharmaciens</strong> et <strong>sages-femmes</strong>.</li><li>Elle est <strong>possible</strong> pour les autres professionnels de santé et les usagers.</li><li>Les déclarations sont faites au <strong>CEIP-A</strong> (Centre d'évaluation et d'information sur la pharmacodépendance et l'addictovigilance) du territoire concerné.</li><li>L'<strong>ANSM</strong> pilote le réseau des 13 CEIP-A en France.</li></ul>"},{"i":"f7aa5dfb9fb8","n":181,"o":"181-10","u":"Définitions","t":"Connaître la pharmacodépendance ou addictovigilance","q":"Quelles sont les substances qui sont délibérément exclues du champ de l'addictovigilance ?","a":"<p>Les substances exclues du champ de l'addictovigilance sont l'<strong>alcool éthylique</strong> et le <strong>tabac</strong>.</p>"},{"i":"24261d71a85d","n":181,"o":"181-11","u":"Définitions","t":"Connaître l'hémovigilance","q":"Quels sont les effets indésirables receveurs (EIR) les plus fréquemment rencontrés en hémovigilance ?","a":"<ul><li>Les <strong>réactions allergiques</strong>.</li><li>Les <strong>réactions fébriles non hémolytiques</strong>.</li><li>L'<strong>œdème de surcharge</strong> (qui est la <strong>1ʳᵉ cause de mortalité</strong> liée à la transfusion).</li><li>Les <strong>incompatibilités immunologiques</strong>.</li></ul>"},{"i":"5193c0ff991c","n":181,"o":"181-11","u":"Définitions","t":"Connaître l'hémovigilance","q":"Comment les effets indésirables receveurs (EIR) sont-ils classifiés selon le délai, la sévérité et l'imputabilité en hémovigilance ?","a":"<ul><li><strong>Délai</strong> :<ul><li><strong>Immédiat</strong> : survient dans les <strong>≤ 8 jours</strong> (aigu pendant et dans les 24 heures).</li><li><strong>Retardé</strong> : survient <strong>> 8 jours</strong> après la transfusion.</li></ul></li><li><strong>Sévérité</strong> :<ul><li><strong>Grade 1</strong> : non sévère.</li><li><strong>Grade 2</strong> : sévère.</li><li><strong>Grade 3</strong> : menace vitale.</li><li><strong>Grade 4</strong> : décès.</li></ul></li><li><strong>Imputabilité</strong> :<ul><li><strong>NE</strong> : non évaluable.</li><li><strong>0</strong> : exclue.</li><li><strong>1</strong> : possible.</li><li><strong>2</strong> : probable.</li><li><strong>3</strong> : certaine.</li></ul></li></ul>"},{"i":"76106db50283","n":181,"o":"181-11","u":"Définitions","t":"Connaître l'hémovigilance","q":"Quelle est la définition de l'hémovigilance ?","a":"<p>L'hémovigilance est un système de <strong>surveillance</strong>, d'<strong>évaluation</strong> et de <strong>prévention</strong> des <strong>incidents et effets indésirables</strong> survenant chez les donneurs ou les receveurs de Produits Sanguins Labiles (PSL) sur l'ensemble de la chaîne transfusionnelle. Elle est pilotée par l'<strong>ANSM</strong>.</p>"},{"i":"a90e055764c2","n":181,"o":"181-11","u":"Définitions","t":"Connaître l'hémovigilance","q":"Quels sont les formulaires de déclaration à utiliser en hémovigilance selon le type d'événement ?","a":"<ul><li>Pour un effet indésirable chez le receveur : <strong>FEIR</strong> (Fiche d'Effet Indésirable Receveur).</li><li>Pour un effet indésirable grave chez le donneur : <strong>FEIGD</strong> (Fiche d'Effet Indésirable Grave Donneur).</li><li>Pour une information post-don : <strong>FIPD</strong> (Fiche d'Information Post-Don).</li><li>Pour un incident grave de la chaîne transfusionnelle : <strong>FIG</strong> (Fiche d'Incident Grave).</li></ul>"},{"i":"fc6e7d6f7728","n":181,"o":"181-11","u":"Définitions","t":"Connaître l'hémovigilance","q":"Quels sont les différents acteurs de l'hémovigilance en France ?","a":"<ul><li>Au niveau <strong>national</strong> : l'<strong>ANSM</strong>, <strong>Santé publique France</strong> et l'<strong>EFS</strong> (Établissement Français du Sang).</li><li>Au niveau <strong>régional</strong> : les coordinateurs et correspondants régionaux.</li><li>Au niveau <strong>local</strong> : les correspondants des ETS (Établissements de Transfusion Sanguine) et des établissements de soins, ainsi que tout professionnel de santé.</li></ul>"},{"i":"2eca868d87f1","n":181,"o":"181-16","u":"Définitions","t":"Connaître l'identitovigilance","q":"L'identitovigilance est-elle une vigilance pilotée par l'ANSM ?","a":"<p>Non, l'identitovigilance <strong>n'est PAS une vigilance pilotée par l'ANSM</strong>, car elle ne concerne pas un produit de santé. C'est un dispositif élargi de sécurité des soins.</p>"},{"i":"67cdc5a7958f","n":181,"o":"181-16","u":"Définitions","t":"Connaître l'identitovigilance","q":"Quelle est la définition de l'identitovigilance ?","a":"<p>L'identitovigilance est l'ensemble des mesures visant la <strong>prévention des erreurs d'identité des patients</strong> à toutes les étapes du processus de soins, notamment en établissement de santé. C'est la « dernière-née » des vigilances.</p>"},{"i":"e24d632caa5d","n":181,"o":"181-16","u":"Définitions","t":"Connaître l'identitovigilance","q":"Quelles sont les mesures concrètes de l'identitovigilance ?","a":"<ul><li>La mise en place d'un <strong>bracelet d'identification du patient</strong>.</li><li>La <strong>vérification de l'identité</strong> du patient avant tout acte de soins.</li></ul>"},{"i":"1062307b33d4","n":181,"o":"181-17","u":"Définitions","t":"Connaître l'infectiovigilance","q":"Qu'est-ce que l'infectiovigilance ?","a":"<p>L'infectiovigilance est un système de <strong>veille sanitaire</strong> spécifique aux <strong>infections associées aux soins (IAS)</strong>, visant à les prévenir et les surveiller.</p>"},{"i":"9fd640ce46d3","n":181,"o":"181-17","u":"Définitions","t":"Connaître l'infectiovigilance","q":"Pourquoi est-il important de ne pas confondre l'agence responsable de l'infectiovigilance avec l'ANSM ?","a":"<p>Il s'agit d'un <strong>piège classique de l'EDN</strong>. Bien que l'<strong>ANSM (Agence nationale de sécurité du médicament et des produits de santé)</strong> participe à la sécurité sanitaire, la responsabilité directe de l'infectiovigilance incombe à <strong>Santé publique France</strong>.</p>"},{"i":"de1d0807a40f","n":181,"o":"181-17","u":"Définitions","t":"Connaître l'infectiovigilance","q":"Quelle agence est responsable de la gestion de l'infectiovigilance en France ?","a":"<p>En France, l'infectiovigilance est gérée par <strong>Santé publique France</strong>.</p>"},{"i":"89b96ef3adfa","n":181,"o":"181-2","u":"Définitions","t":"Connaître la définition de la crise sanitaire","q":"Selon la définition pour l'EDN, qu'est-ce qu'une crise sanitaire ?","a":"<p>Une crise sanitaire est une situation <strong>imprévue</strong> et <strong>complexe</strong>, présentant un caractère de <strong>gravité potentiel ou avéré</strong>, et nécessitant des <strong>actions immédiates</strong> avec des <strong>moyens de gestion exceptionnels</strong>, le plus souvent transversaux.</p>"},{"i":"8e0eede1418b","n":181,"o":"181-2","u":"Définitions","t":"Connaître la définition de la crise sanitaire","q":"Quels sont les trois éléments clés à retenir pour définir une crise sanitaire ?","a":"<ul><li>Une situation <strong>imprévue</strong> et <strong>complexe/transversale</strong>.</li><li>Un caractère de <strong>gravité</strong>.</li><li>La nécessité d'<strong>imposer des moyens exceptionnels</strong>.</li></ul>"},{"i":"f9bb977c9ce5","n":181,"o":"181-2","u":"Définitions","t":"Connaître la définition de la crise sanitaire","q":"Citez des exemples historiques de crises sanitaires majeures en France qui illustrent cette définition.","a":"<ul><li>L'affaire du <strong>sang contaminé</strong>.</li><li>La crise de la <strong>vache folle</strong>.</li><li>La <strong>canicule de 2003</strong>.</li><li>L'affaire du <strong>Mediator®</strong>.</li><li>La pandémie de <strong>COVID-19</strong>.</li></ul>"},{"i":"1e47c111bd42","n":181,"o":"181-27","u":"Définitions","t":"Savoir qu'il existe une liste des événements qui ne devraient jamais arriver en établissement de santé selon l'ANSM","q":"Citez cinq exemples de \"never events\" relatifs aux médicaments ou à leur administration, tels qu'identifiés par l'ANSM.","a":"<ul><li>Erreur de prise en charge des patients sous <strong>anticoagulants</strong>.</li><li>Erreur d'administration du <strong>chlorure de potassium (KCl) injectable</strong>.</li><li>Erreur d'administration par <strong>voie intrathécale au lieu d'intraveineuse</strong>.</li><li><strong>Surdosage en anticancéreux</strong> (notamment en pédiatrie).</li><li>Erreur d'administration d'<strong>insuline</strong>.</li></ul>"},{"i":"3fe4e7839ea3","n":181,"o":"181-27","u":"Définitions","t":"Savoir qu'il existe une liste des événements qui ne devraient jamais arriver en établissement de santé selon l'ANSM","q":"Quels sont les domaines principalement concernés par les \"never events\" tels qu'établis par l'ANSM ?","a":"<p>Les \"never events\" établis par l'ANSM portent essentiellement sur les <strong>médicaments et leur administration</strong>.</p>"},{"i":"6e2404896258","n":181,"o":"181-27","u":"Définitions","t":"Savoir qu'il existe une liste des événements qui ne devraient jamais arriver en établissement de santé selon l'ANSM","q":"Quel organisme français a établi une liste des \"never events\" et en quelle année ?","a":"<p>C'est l'<strong>ANSM</strong> qui a établi une liste de \"never events\" en <strong>2012</strong>.</p>"},{"i":"b29bba921424","n":181,"o":"181-27","u":"Définitions","t":"Savoir qu'il existe une liste des événements qui ne devraient jamais arriver en établissement de santé selon l'ANSM","q":"Quelle est la définition des \"never events\" dans le contexte des établissements de santé ?","a":"<p>Les \"never events\" sont des <strong>événements indésirables graves (EIGS)</strong>, évitables, liés à des produits de santé qui ne devraient <strong>jamais survenir</strong> si des mesures de prévention adéquates sont mises en œuvre.</p>"},{"i":"16a6f940052c","n":181,"o":"181-3","u":"Définitions","t":"Connaître la définition de la veille et de la vigilance sanitaire","q":"Comment distinguer la veille sanitaire, la vigilance sanitaire et la surveillance sanitaire ?","a":"<ul><li>La <strong>veille sanitaire</strong> consiste à <strong>guetter le signal</strong>, identifier si un événement peut devenir un risque.</li><li>La <strong>vigilance sanitaire</strong> désigne un <strong>dispositif réglementé ciblé</strong>, formalisé autour de risques spécifiques.</li><li>La <strong>surveillance sanitaire</strong> correspond à la <strong>mesure en continu</strong> de données de morbidité et de mortalité pour l'aide à la décision en santé publique.</li></ul>"},{"i":"47fe9adf647e","n":181,"o":"181-3","u":"Définitions","t":"Connaître la définition de la veille et de la vigilance sanitaire","q":"Quelle est la définition de la veille sanitaire ?","a":"<p>La veille sanitaire est un processus continu de recueil, d'identification, d'évaluation et d'investigation des <strong>risques d'événements ou des événements indésirables</strong> de toute nature associés à une menace potentielle pour la <strong>santé humaine</strong>. Elle contribue à la sécurité sanitaire.</p>"},{"i":"fccfb823f400","n":181,"o":"181-3","u":"Définitions","t":"Connaître la définition de la veille et de la vigilance sanitaire","q":"Quelle est la définition de la vigilance sanitaire ?","a":"<p>La vigilance sanitaire représente l'ensemble des <strong>dispositifs réglementés de surveillance</strong> des événements indésirables et des incidents survenant chez l'homme. Initialement liés aux produits de santé, ces dispositifs s'élargissent aux infections nosocomiales et aux événements indésirables graves (EIGS) liés aux soins.</p>"},{"i":"288318a49b04","n":181,"o":"181-4","u":"Définitions","t":"Connaître la définition des produits de santé destinés à l'homme","q":"Quel est le périmètre réglementaire de l'ANSM concernant les produits de santé destinés à l'homme ?","a":"<p>Le périmètre réglementaire de l'ANSM couvre le produit <strong>tout au long de son cycle de vie</strong>, depuis les <strong>essais initiaux</strong> jusqu'à la <strong>surveillance après mise sur le marché</strong>.</p>"},{"i":"557803d5b1ab","n":181,"o":"181-4","u":"Définitions","t":"Connaître la définition des produits de santé destinés à l'homme","q":"Quels sont les quatre grands ensembles de produits de santé destinés à l'homme concernés par la réglementation ?","a":"<ul><li>Les <strong>médicaments</strong></li><li>Les <strong>produits biologiques</strong></li><li>Les <strong>dispositifs médicaux</strong></li><li>Les <strong>produits cosmétiques et de tatouage</strong></li></ul>"},{"i":"6b7d17bbb8ed","n":181,"o":"181-4","u":"Définitions","t":"Connaître la définition des produits de santé destinés à l'homme","q":"Quelle agence est compétente pour la régulation des produits de santé destinés à l'homme en France ?","a":"<p>L'agence compétente est l'<strong>ANSM</strong> (Agence Nationale de Sécurité du Médicament et des produits de santé).</p>"},{"i":"dc7479b45648","n":181,"o":"181-4","u":"Définitions","t":"Connaître la définition des produits de santé destinés à l'homme","q":"Quel type de produits sont inclus dans la catégorie 'Médicaments' selon la réglementation actuelle ?","a":"<ul><li>Tous les <strong>médicaments</strong> (avant et après <strong>AMM</strong>) et matières premières.</li><li>Les médicaments dérivés du sang.</li><li>Les <strong>stupéfiants</strong> et <strong>psychotropes</strong>.</li><li>Les <strong>vaccins</strong>.</li><li>Les produits homéopathiques et à base de plantes.</li><li>Les préparations <strong>magistrales</strong> et <strong>hospitalières</strong>.</li></ul>"},{"i":"f0831f761b02","n":181,"o":"181-4","u":"Définitions","t":"Connaître la définition des produits de santé destinés à l'homme","q":"Donnez des exemples des produits classés comme 'Produits biologiques' parmi les produits de santé destinés à l'homme.","a":"<ul><li><strong>Organes</strong>, <strong>tissus</strong>, <strong>cellules</strong> à des fins thérapeutiques.</li><li>Produits de <strong>thérapie cellulaire et génique</strong>.</li><li><strong>Produits sanguins labiles (PSL)</strong>.</li><li>Produits thérapeutiques annexes.</li></ul>"},{"i":"fcc8e859f178","n":181,"o":"181-4","u":"Définitions","t":"Connaître la définition des produits de santé destinés à l'homme","q":"Que comprend la catégorie des 'Dispositifs médicaux' dans le cadre des produits de santé destinés à l'homme ?","a":"<p>Elle comprend les <strong>DM thérapeutiques</strong>, les <strong>DM de diagnostic</strong>, les <strong>DM de diagnostic in vitro (DIV)</strong>, ainsi que les <strong>plateaux techniques</strong>.</p>"},{"i":"137f6f7556e5","n":181,"o":"181-9","u":"Définitions","t":"Connaître la pharmacovigilance","q":"Qui est concerné par l'obligation ou la possibilité de déclarer un effet indésirable en pharmacovigilance, et à qui doit se faire cette déclaration ?","a":"<ul><li>Les <strong>médecins, sages-femmes, chirurgiens-dentistes, et pharmaciens</strong> ont une <strong>obligation de déclaration</strong>.</li><li>Les autres professionnels de santé, les patients et les associations ont une <strong>possibilité de déclarer</strong>.</li><li>Les <strong>firmes pharmaceutiques déclarent via Eudravigilance</strong>.</li></ul><p>Les déclarations sont faites au <strong>Centre régional de pharmacovigilance (CRPV)</strong> du déclarant. Les entreprises déclarent à l'<strong>EMA via Eudravigilance</strong>.</p>"},{"i":"1779beb08ca6","n":181,"o":"181-9","u":"Définitions","t":"Connaître la pharmacovigilance","q":"Quels sont les différents types d'effets indésirables à déclarer en pharmacovigilance ?","a":"<p>Il faut déclarer <strong>tout effet indésirable suspecté</strong>, qu'il soit <strong>grave ou non</strong>. Ceci inclut les situations de :</p><ul><li>Usage conforme ou non à l'AMM</li><li>Erreur médicamenteuse</li><li>Abus</li><li>Mésusage</li><li>Surdosage</li><li>Exposition professionnelle</li></ul><p>Une attention particulière doit être portée aux <strong>effets graves et inattendus</strong>.</p>"},{"i":"4bcc27dd43f3","n":181,"o":"181-9","u":"Définitions","t":"Connaître la pharmacovigilance","q":"Quelle est la définition de la pharmacovigilance ?","a":"<p>La pharmacovigilance est l'ensemble des activités de <strong>surveillance</strong>, d'<strong>évaluation</strong>, de <strong>prévention</strong> et de <strong>gestion du risque</strong> d'effet indésirable résultant de l'utilisation des médicaments et produits à usage humain. Elle est pilotée par l'<strong>ANSM</strong>.</p>"},{"i":"9e43881b4dec","n":181,"o":"181-9","u":"Définitions","t":"Connaître la pharmacovigilance","q":"Quels sont les canaux de déclaration en pharmacovigilance et quelles sont les conséquences de ces déclarations ?","a":"<p>Les déclarations peuvent se faire via :</p><ul><li>Le <strong>portail national de signalement des événements sanitaires indésirables</strong> (signalement-sante.gouv.fr)</li><li>Courrier, fax, formulaire CERFA, ou application dédiée.</li></ul><p>Après transmission par le CRPV à l'ANSM, des mesures peuvent être prises telles que :</p><ul><li>Information des professionnels de santé</li><li>Modification du Résumé des Caractéristiques du Produit (RCP)</li><li>Retrait ou suspension d'Autorisation de Mise sur le Marché (AMM)</li><li>Lettres d'alerte</li><li>Ajout de pictogrammes.</li></ul>"}]};